window.openEconomicTrendChart = function(key, tf) {
      currentTrendKey = key;
      const data = economicTrendData[key];
      if (!data) return;

      const availableTfs = Object.keys(data.timeframes);
      if (!tf || !availableTfs.includes(tf)) {
        currentTrendTf = availableTfs[0]; // 태초(최초집계) 시점부터 기본 표출
      } else {
        currentTrendTf = tf;
      }

            // Update Quick Indicator Switcher Buttons
      document.querySelectorAll('.trend-ind-btn').forEach(b => b.classList.remove('active'));
      const activeBtn = document.getElementById('indBtn-' + key);
      if (activeBtn) {
        activeBtn.classList.add('active');
        try { activeBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' }); } catch(e){}
      }

      document.getElementById('trendModalTitle').textContent = data.title;
      document.getElementById('trendModalCategory').textContent = data.category;
      document.getElementById('trendStatCurrent').textContent = data.current;
      document.getElementById('trendStatHigh').textContent = data.high;
      document.getElementById('trendStatLow').textContent = data.low;
      document.getElementById('trendStatChg').textContent = data.chg;

      // Render Timeframe buttons
      const tfContainer = document.getElementById('trendTfTabs');
      tfContainer.innerHTML = '';

      availableTfs.forEach(t => {
        const btn = document.createElement('button');
        btn.className = `trend-tf-btn ${t === currentTrendTf ? 'active' : ''}`;
        btn.textContent = t;
        btn.onclick = () => {
          currentTrendTf = t;
          document.querySelectorAll('.trend-tf-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          
      renderPresidentialSvgChart('weekly');
renderSvgTrendChart(currentTrendKey, t);
        };
        tfContainer.appendChild(btn);
      });

      // Render Milestones
      const milestoneList = document.getElementById('trendMilestonesList');
      milestoneList.innerHTML = '';
      data.inflections.forEach(m => {
        const row = document.createElement('div');
        row.className = 'milestone-row';
        row.style.padding = '12px 14px';
        row.style.marginBottom = '10px';
        row.style.background = 'rgba(255,255,255,0.03)';
        row.style.borderRadius = '10px';
        row.style.border = '1px solid rgba(255,255,255,0.06)';
        row.innerHTML = `
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
            <div class="milestone-date" style="font-weight: 800; color: #38BDF8; font-size: 12px;">📅 ${m.date} ${m.val ? `· 당시 수치: <strong style='color:#FACC15;'>${m.val}</strong>` : ''}</div>
            <span style="font-size: 10.5px; background: rgba(56, 189, 248, 0.15); color: #38BDF8; padding: 2px 7px; border-radius: 4px; font-weight: 700;">결정적 변곡점</span>
          </div>
          <div class="milestone-body">
            <div class="milestone-name" style="font-size: 13.5px; font-weight: 800; color: #F8FAFC; margin-bottom: 5px;">📌 ${m.event}</div>
            <div style="font-size: 12px; color: #CBD5E1; line-height: 1.5; margin-bottom: 4px;">
              <strong style="color: #F87171;">⚡ 상호작용한 거시경제 변화:</strong> ${m.crossImpact || m.desc || '글로벌 유동성 및 통상 환경 연계'}
            </div>
            <div style="font-size: 11.5px; color: #34D399; line-height: 1.45;">
              <strong style="color: #FACC15;">🔮 향후 시사점:</strong> ${m.forecastNote || '구조적 안정성 확보 및 정책 여력 축적'}
            </div>
          </div>
        `;
        milestoneList.appendChild(row);
      });

      // Render Insight
      document.getElementById('trendInsightText').textContent = data.insight;

      // Render SVG Chart
      renderSvgTrendChart(currentTrendKey, currentTrendTf);

      const modal = document.getElementById('trendChartModal');
      if (modal) modal.classList.add('active');
      document.body.style.overflow = 'hidden';
    };

    window.closeTrendChartModal = function() {
      const modal = document.getElementById('trendChartModal');
      if (modal) modal.classList.remove('active');
      document.body.style.overflow = '';
      const tooltip = document.getElementById('chartTooltipBox');
      if (tooltip) tooltip.style.display = 'none';
    };

    window.closeTrendChartModalOnOverlay = function(e) {
      if (e && e.target && e.target.id === 'trendChartModal') {
        window.closeTrendChartModal();
      }
    };

    
    // =========================================================================
    // 🔬 Econometrics Self-Service Toolkit Functions (OLS, Bollinger, Cross, Sim)
    // =========================================================================
    let isOlsEnabled = true;
    let isBollingerEnabled = false;
    let isSimulatorOpen = false;
    let overlayIndicatorKey = 'none';

    window.toggleOlsTrendline = function() {
      isOlsEnabled = !isOlsEnabled;
      const btn = document.getElementById('btnToggleOls');
      if (btn) {
        btn.style.background = isOlsEnabled ? 'rgba(56, 189, 248, 0.25)' : 'rgba(255, 255, 255, 0.06)';
        btn.style.color = isOlsEnabled ? '#38BDF8' : '#D1D5DB';
      }
      renderSvgTrendChart(currentTrendKey, currentTrendTf);
    };

    window.toggleBollingerBands = function() {
      isBollingerEnabled = !isBollingerEnabled;
      const btn = document.getElementById('btnToggleBollinger');
      if (btn) {
        btn.style.background = isBollingerEnabled ? 'rgba(52, 211, 153, 0.25)' : 'rgba(255, 255, 255, 0.06)';
        btn.style.color = isBollingerEnabled ? '#34D399' : '#D1D5DB';
      }
      renderSvgTrendChart(currentTrendKey, currentTrendTf);
    };

    window.toggleWhatIfSimulator = function() {
      isSimulatorOpen = !isSimulatorOpen;
      const box = document.getElementById('whatIfSimulatorBox');
      const btn = document.getElementById('btnToggleSimulator');
      if (box) box.style.display = isSimulatorOpen ? 'block' : 'none';
      if (btn) {
        btn.style.background = isSimulatorOpen ? '#FACC15' : 'rgba(234, 179, 8, 0.15)';
        btn.style.color = isSimulatorOpen ? '#000' : '#FACC15';
      }
    };

    window.changeOverlayIndicator = function(key) {
      overlayIndicatorKey = key;
      renderSvgTrendChart(currentTrendKey, currentTrendTf);
    };

    window.runMacroSimulation = function() {
      const rateVal = parseInt(document.getElementById('simRateSlider').value || 0);
      const oilVal = parseInt(document.getElementById('simOilSlider').value || 0);
      document.getElementById('simRateVal').textContent = (rateVal > 0 ? '+' : '') + rateVal + 'bp';
      document.getElementById('simOilVal').textContent = (oilVal > 0 ? '+' : '') + '$' + oilVal;

      const summary = document.getElementById('simResultSummary');
      if (rateVal === 0 && oilVal === 0) {
        summary.innerHTML = '⚡ 기준 시나리오: 현재 거시 예측 경로를 유지 중입니다.';
        summary.style.color = '#34D399';
      } else {
        let fxImp = (rateVal * -0.35 + oilVal * 1.8).toFixed(1);
        let gdpImp = (rateVal * -0.003 - oilVal * 0.015).toFixed(2);
        summary.innerHTML = `🔮 <strong>시뮬레이션 결과:</strong> 환율 예상 변동 <span style="color:#FACC15;">${fxImp > 0 ? '+' : ''}${fxImp}원</span>, 성장률 예상 변동 <span style="color:#38BDF8;">${gdpImp > 0 ? '+' : ''}${gdpImp}%p</span> (탄력성 계수 적용)`;
        summary.style.color = '#F8FAFC';
      }
    };

function renderSvgTrendChart(key, tf) {
      const item = economicTrendData[key];
      if (!item || !item.timeframes || !item.timeframes[tf]) return;

      const pts = item.timeframes[tf];
      const svg = document.getElementById('svgTrendChart');
      if (!svg) return;

      const width = 640;
      const height = 260;
      const padL = 60;
      const padR = (typeof overlayIndicatorKey !== 'undefined' && overlayIndicatorKey !== 'none') ? 60 : 35;
      const padT = 30;
      const padB = 40;

      const vals = pts.map(p => p.val);
      let minV = Math.min(...vals);
      let maxV = Math.max(...vals);
      if (minV === maxV) {
        minV -= 1;
        maxV += 1;
      }
      const vRange = maxV - minV;
      const graphMin = minV - vRange * 0.1;
      const graphMax = maxV + vRange * 0.1;
      const graphRange = graphMax - graphMin;

      const chartW = width - padL - padR;
      const chartH = height - padT - padB;

      const coords = pts.map((p, i) => {
        const x = padL + (i / (pts.length - 1 || 1)) * chartW;
        const y = padT + chartH - ((p.val - graphMin) / graphRange) * chartH;
        return { x, y, ...p };
      });

      let svgContent = `
        <defs>
          <linearGradient id="chartGrad_${key}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#38BDF8" stop-opacity="0.45" />
            <stop offset="65%" stop-color="#0071E3" stop-opacity="0.12" />
            <stop offset="100%" stop-color="#0071E3" stop-opacity="0.0" />
          </linearGradient>
          <linearGradient id="chartGradOverlay" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#F59E0B" stop-opacity="0.35" />
            <stop offset="100%" stop-color="#F59E0B" stop-opacity="0.0" />
          </linearGradient>
          <filter id="chartGlow_${key}" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="3.5" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
      `;

      // Grid lines
      const yTicks = 4;
      for (let i = 0; i <= yTicks; i++) {
        const tVal = graphMin + (graphRange * i) / yTicks;
        const tY = padT + chartH - (i / yTicks) * chartH;
        const formattedVal = Math.abs(tVal) >= 100 ? tVal.toFixed(0) : tVal.toFixed(1);
        svgContent += `
          <line x1="${padL}" y1="${tY}" x2="${width - padR}" y2="${tY}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="3 3" />
          <text x="${padL - 10}" y="${tY + 4}" fill="#64748B" font-size="10.5" font-family="sans-serif" text-anchor="end">${formattedVal}${item.unit || ''}</text>
        `;
      }

      // OLS Linear Regression Trendline
      if (typeof isOlsEnabled !== 'undefined' && isOlsEnabled && pts.length >= 2) {
        const n = pts.length;
        let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;
        pts.forEach((p, idx) => {
          sumX += idx;
          sumY += p.val;
          sumXY += idx * p.val;
          sumXX += idx * idx;
        });
        const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX || 1);
        const intercept = (sumY - slope * sumX) / n;
        
        const yStartVal = intercept;
        const yEndVal = slope * (n - 1) + intercept;
        const y1 = padT + chartH - ((yStartVal - graphMin) / graphRange) * chartH;
        const y2 = padT + chartH - ((yEndVal - graphMin) / graphRange) * chartH;
        
        svgContent += `
          <line x1="${padL}" y1="${y1}" x2="${width - padR}" y2="${y2}" stroke="#38BDF8" stroke-width="2" stroke-dasharray="5 4" opacity="0.85" />
          <text x="${width - padR - 5}" y="${Math.max(padT + 12, y2 - 6)}" fill="#38BDF8" font-size="10" font-weight="700" text-anchor="end">OLS 추세선 (기울기: ${slope > 0 ? '+' : ''}${slope.toFixed(2)})</text>
        `;
      }

      // Bollinger Bands (+-2 sigma)
      if (typeof isBollingerEnabled !== 'undefined' && isBollingerEnabled && pts.length >= 3) {
        const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
        const stdDev = Math.sqrt(vals.map(x => Math.pow(x - mean, 2)).reduce((a, b) => a + b) / vals.length);
        const upperVal = mean + 2 * stdDev;
        const lowerVal = mean - 2 * stdDev;
        const yUpper = padT + chartH - ((upperVal - graphMin) / graphRange) * chartH;
        const yLower = padT + chartH - ((lowerVal - graphMin) / graphRange) * chartH;

        svgContent += `
          <line x1="${padL}" y1="${yUpper}" x2="${width - padR}" y2="${yUpper}" stroke="#34D399" stroke-width="1.5" stroke-dasharray="4 3" opacity="0.75" />
          <text x="${padL + 10}" y="${yUpper - 4}" fill="#34D399" font-size="9.5" font-weight="700">+2σ 상한 임계치 (${upperVal.toFixed(1)})</text>
          <line x1="${padL}" y1="${yLower}" x2="${width - padR}" y2="${yLower}" stroke="#F87171" stroke-width="1.5" stroke-dasharray="4 3" opacity="0.75" />
          <text x="${padL + 10}" y="${yLower + 12}" fill="#F87171" font-size="9.5" font-weight="700">-2σ 하한 지지선 (${lowerVal.toFixed(1)})</text>
        `;
      }

      // Path
      let pathD = '';
      let areaD = '';
      coords.forEach((c, i) => {
        if (i === 0) {
          pathD += `M ${c.x} ${c.y}`;
          areaD += `M ${c.x} ${padT + chartH} L ${c.x} ${c.y}`;
        } else {
          const prev = coords[i - 1];
          const cx1 = (prev.x + c.x) / 2;
          const cy1 = prev.y;
          const cx2 = (prev.x + c.x) / 2;
          const cy2 = c.y;
          pathD += ` C ${cx1} ${cy1}, ${cx2} ${cy2}, ${c.x} ${c.y}`;
          areaD += ` C ${cx1} ${cy1}, ${cx2} ${cy2}, ${c.x} ${c.y}`;
        }
      });
      const lastC = coords[coords.length - 1];
      areaD += ` L ${lastC.x} ${padT + chartH} Z`;

      svgContent += `<path d="${areaD}" fill="url(#chartGrad_${key})" />`;
      svgContent += `<path d="${pathD}" fill="none" stroke="#38BDF8" stroke-width="3" filter="url(#chartGlow_${key})" stroke-linecap="round" />`;

      // Dual-Axis Cross Overlay Indicator
      if (typeof overlayIndicatorKey !== 'undefined' && overlayIndicatorKey !== 'none' && overlayIndicatorKey !== key && economicTrendData[overlayIndicatorKey]) {
        const oItem = economicTrendData[overlayIndicatorKey];
        const oTf = oItem.timeframes[tf] ? tf : Object.keys(oItem.timeframes)[0];
        const oPts = oItem.timeframes[oTf];
        if (oPts && oPts.length >= 2) {
          const oVals = oPts.map(p => p.val);
          let oMin = Math.min(...oVals);
          let oMax = Math.max(...oVals);
          if (oMin === oMax) { oMin -= 1; oMax += 1; }
          const oRange = (oMax - oMin) * 1.2;
          const oGraphMin = oMin - oRange * 0.1;
          
          let oPathD = '';
          oPts.forEach((p, idx) => {
            const ox = padL + (idx / (oPts.length - 1 || 1)) * chartW;
            const oy = padT + chartH - ((p.val - oGraphMin) / (oRange || 1)) * chartH;
            if (idx === 0) oPathD += `M ${ox} ${oy}`;
            else oPathD += ` L ${ox} ${oy}`;
          });

          svgContent += `<path d="${oPathD}" fill="none" stroke="#F59E0B" stroke-width="2.5" stroke-dasharray="4 2" stroke-linecap="round" />`;
          svgContent += `<text x="${width - padR + 8}" y="${padT + 12}" fill="#F59E0B" font-size="10" font-weight="800">우측축: ${oItem.title.split(' ')[0]}</text>`;
        }
      }

      // Data points and labels
      coords.forEach((c, idx) => {
        const step = coords.length > 12 ? Math.ceil(coords.length / 8) : 1;
        if (idx === 0 || idx === coords.length - 1 || idx % step === 0 || c.isForecast) {
          svgContent += `
            <text x="${c.x}" y="${padT + chartH + 18}" fill="${c.isForecast ? '#C084FC' : '#94A3B8'}" font-size="10.5" font-family="sans-serif" text-anchor="middle" font-weight="${c.isForecast ? '800' : '400'}">${c.date}</text>
          `;
        }

        const ptColor = c.isForecast ? '#C084FC' : (idx === coords.length - 1 ? '#38BDF8' : '#60A5FA');
        const ptRadius = c.isForecast ? 5.5 : (idx === coords.length - 1 ? 5 : 3.5);

        svgContent += `
          <circle cx="${c.x}" cy="${c.y}" r="${ptRadius}" fill="${ptColor}" stroke="#0F172A" stroke-width="2" cursor="pointer" onmouseover="showChartTooltip(event, '${c.date}', '${c.val}${item.unit || ''}', '${c.event || ''}')" onmouseout="hideChartTooltip()" />
        `;
      });

      svg.innerHTML = svgContent;
    }

    window.showChartTooltip = function(e, date, val, eventText) {
      const box = document.getElementById('chartTooltipBox');
      if (!box) return;
      document.getElementById('tooltipDate').textContent = `📅 ${date}`;
      document.getElementById('tooltipVal').textContent = val;
      const evEl = document.getElementById('tooltipEvent');
      if (eventText) {
        evEl.textContent = `⚡ ${eventText}`;
        evEl.style.display = 'block';
      } else {
        evEl.style.display = 'none';
      }
      box.style.display = 'flex';
    };

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        window.closeTrendChartModal();
      }
    });
  

