let currentEconRange = 'all';
let currentMdsSelected = 'usdkrw';

function switchEconTab(tabId) {
  document.querySelectorAll('.econ-tab-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.econ-tab-pane').forEach(p => p.classList.remove('active'));
  
  const targetPane = document.getElementById(tabId);
  if (targetPane) targetPane.classList.add('active');
  
  // Find matching button
  const btns = document.querySelectorAll('.econ-tab-btn');
  btns.forEach(b => {
    if (b.getAttribute('onclick') && b.getAttribute('onclick').includes(tabId)) {
      b.classList.add('active');
    }
  });

  // Trigger rendering depending on tab
  if (tabId === 'tab-notion-indicators') filterNotionCards('all');
  else if (tabId === 'tab-thinktanks') renderThinkTanks();
  else if (tabId === 'tab-inception') renderInceptionTimeSeries();
  else if (tabId === 'tab-cross') renderCrossAnalysis();
  else if (tabId === 'tab-corr') renderCorrelationHeatmap();
  else if (tabId === 'tab-reg') runRegressionAnalysis();
  else if (tabId === 'tab-cluster') renderClusterAnalysis();
  else if (tabId === 'tab-mds') renderMDSAnalysis();
  else if (tabId === 'tab-sites') renderOfficialSites();
  else if (tabId === 'tab-global-debt-pir') renderGlobalDebtPirLab();
}

// ============================================================================
// Notion 11 Macro Indicators & Think Tanks Interactive Cascading Engine
// ============================================================================

function toggleNotionGroup(groupId) {
  const group = document.getElementById(groupId);
  if (!group) return;
  group.classList.toggle('open');
  
  // Update sector chip active state if single group is toggled
  const secNum = groupId.replace('notion-group-', '');
  document.querySelectorAll('.notion-sector-chip').forEach(c => c.classList.remove('active'));
  const targetChip = document.getElementById('chip-sec-' + secNum);
  if (targetChip && group.classList.contains('open')) {
    targetChip.classList.add('active');
  }
}

function expandAllNotionGroups() {
  const groups = document.querySelectorAll('.notion-accordion-group');
  groups.forEach((g, idx) => {
    setTimeout(() => {
      g.classList.add('open');
      g.classList.add('cascading-open');
    }, idx * 45); // Staggered 45ms cascade reveal! ("쫘르르르 펼쳐짐")
  });
  document.querySelectorAll('.notion-sector-chip').forEach(c => c.classList.add('active'));
}

function collapseAllNotionGroups() {
  const groups = document.querySelectorAll('.notion-accordion-group');
  groups.forEach(g => {
    g.classList.remove('open');
    g.classList.remove('cascading-open');
  });
  document.querySelectorAll('.notion-sector-chip').forEach(c => c.classList.remove('active'));
}

function selectNotionSector(secNum) {
  // Update chip active
  document.querySelectorAll('.notion-sector-chip').forEach(c => c.classList.remove('active'));
  const targetChip = document.getElementById('chip-sec-' + secNum);
  if (targetChip) targetChip.classList.add('active');

  const targetGroup = document.getElementById('notion-group-' + secNum);
  if (targetGroup) {
    targetGroup.classList.add('open');
    targetGroup.classList.add('cascading-open');
    targetGroup.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

function filterNotionCards(type) {
  document.querySelectorAll('#tab-notion-indicators .econ-mini-btn').forEach(b => b.classList.remove('active'));
  const btnId = type === 'all' ? 'btnNotionFilterAll' :
                type === 'leading' ? 'btnNotionFilterLeading' :
                type === 'coincident' ? 'btnNotionFilterCoincident' : 'btnNotionFilterLagging';
  const targetBtn = document.getElementById(btnId);
  if (targetBtn) targetBtn.classList.add('active');

  const items = document.querySelectorAll('.notion-ind-item');
  items.forEach(el => {
    if (type === 'all') {
      el.style.display = 'flex';
    } else if (type === 'leading') {
      el.style.display = el.classList.contains('notion-card-leading') ? 'flex' : 'none';
    } else if (type === 'coincident') {
      el.style.display = el.classList.contains('notion-card-coincident') ? 'flex' : 'none';
    } else if (type === 'lagging') {
      el.style.display = el.classList.contains('notion-card-lagging') ? 'flex' : 'none';
    }
  });

  // Automatically expand groups that contain visible items
  const groups = document.querySelectorAll('.notion-accordion-group');
  groups.forEach(g => {
    if (type === 'all') {
      g.classList.add('open');
    } else {
      const visibleItems = g.querySelectorAll('.notion-ind-item:not([style*="display: none"])');
      if (visibleItems.length > 0) {
        g.classList.add('open');
      } else if (g.id !== 'notion-group-7') {
        g.classList.remove('open');
      }
    }
  });
}

