function renderMDSAnalysis() {
  const nodes = [
    { id: 'usdkrw', name: '원/달러 환율', x: 220, y: 100, color: '#38bdf8' },
    { id: 'fed_rate', name: '美 연준 기준금리', x: 760, y: 90, color: '#fbbf24' },
    { id: 'bok_rate', name: '韓 기준금리', x: 620, y: 130, color: '#f59e0b' },
    { id: 'kr_gdp', name: '韓 실질 GDP', x: 500, y: 260, color: '#34d399' },
    { id: 'kospi', name: 'KOSPI 지수', x: 260, y: 240, color: '#a855f7' },
    { id: 'wti', name: 'WTI 원유', x: 800, y: 230, color: '#ef4444' }
  ];

  let svgHtml = `
    <svg viewBox="0 0 1000 360" style="width:100%; height:100%;">
      <!-- Center Origin & Circles -->
      <circle cx="500" cy="180" r="140" fill="none" stroke="rgba(56,189,248,0.1)" stroke-dasharray="3 3"/>
      <circle cx="500" cy="180" r="70" fill="none" stroke="rgba(56,189,248,0.1)" stroke-dasharray="3 3"/>
      <line x1="500" y1="20" x2="500" y2="340" stroke="rgba(255,255,255,0.08)"/>
      <line x1="80" y1="180" x2="920" y2="180" stroke="rgba(255,255,255,0.08)"/>
  `;

  // Draw distance lines from selected node
  const activeNode = nodes.find(n => n.id === currentMdsSelected) || nodes[0];
  nodes.forEach(n => {
    if (n.id !== activeNode.id) {
      svgHtml += `<line x1="${activeNode.x}" y1="${activeNode.y}" x2="${n.x}" y2="${n.y}" stroke="rgba(56,189,248,0.25)" stroke-dasharray="4 4"/>`;
    }
  });

  nodes.forEach(n => {
    const isAct = n.id === activeNode.id;
    svgHtml += `
      <g style="cursor:pointer;" onclick="selectMdsNode('${n.id}')">
        <circle cx="${n.x}" cy="${n.y}" r="${isAct ? 16 : 10}" fill="${n.color}" fill-opacity="${isAct ? '0.4' : '0.2'}" stroke="${n.color}" stroke-width="${isAct ? 3 : 2}}"/>
        <circle cx="${n.x}" cy="${n.y}" r="4" fill="#ffffff"/>
        <text x="${n.x}" y="${n.y + 24}" fill="${isAct ? '#ffffff' : '#94a3b8'}" font-size="${isAct ? '13' : '11'}" font-weight="800" text-anchor="middle">${n.name}</text>
      </g>
    `;
  });

  svgHtml += `</svg>`;
  document.getElementById('svgMdsContainer').innerHTML = svgHtml;
}

function selectMdsNode(id) {
  currentMdsSelected = id;
  renderMDSAnalysis();
  const it = ECON_MACRO_DATA[id];
  if (!it) return;

  document.getElementById('mdsSelectedTitle').textContent = `선택 지표: ${it.name} 다차원 척도 지각도 분석`;
  let desc = `지각도 상에서 <strong>${it.name}</strong>은 `;
  if (id === 'usdkrw') desc += 'KOSPI와 대척점에 위치하여 전통적인 시장 위기 시 안전자산 및 통화 헤지 수단으로 작용합니다.';
  else if (id === 'fed_rate') desc += '한은 기준금리와 가장 가까운 유클리드 거리를 보이며 글로벌 통화정책 동조화를 이끕니다.';
  else if (id === 'kospi') desc += '실질 GDP 성장률 및 글로벌 유동성과 높은 상관 군집을 형성하며 경제 펀더멘털을 선행 반영합니다.';
  else if (id === 'wti') desc += '스태그플레이션 축에 인접하여 공급 충격 국면에서 인플레이션 압력을 견인합니다.';
  else desc += '다른 주요 거시 지표들과 안정적인 거리 벡터를 유지하며 포트폴리오 다변화의 핵심 축을 구성합니다.';
  document.getElementById('mdsSelectedDesc').innerHTML = desc;
}

