function jumpToEconometricsLab(indicatorKey) {
  if (typeof closeTrendChartModal === 'function') closeTrendChartModal();
  const lab = document.getElementById('econometrics-lab');
  if (lab) lab.scrollIntoView({ behavior: 'smooth' });

  let targetEconKey = indicatorKey;
  if (indicatorKey === 'rate_diff') targetEconKey = 'bok_rate';
  else if (indicatorKey === 'us_yield_curve') targetEconKey = 'fed_rate';
  else if (indicatorKey === 'kr_yield_curve') targetEconKey = 'bok_rate';
  else if (indicatorKey === 'gdp') targetEconKey = 'kr_gdp';
  else if (indicatorKey === 'exports' || indicatorKey === 'clarksons') targetEconKey = 'kospi';

  const sel = document.getElementById('econInceptionSelect');
  if (sel && ECON_MACRO_DATA[targetEconKey]) {
    sel.value = targetEconKey;
  }
  switchEconTab('tab-inception');
}

